// ✅ FIXED: constant-size padding prevents size-based side-channel
const FIXED_BLOCK_SIZE: u64 = 256; // Fixed memory block size

public fun store_agent_memory_fixed(
    wallet: &mut AgentWallet,
    memory_data: vector<u8>,
    ctx: &mut TxContext,
) {
    // Reject if data exceeds fixed block (caller must pre-chunk)
    assert!(vector::length(&memory_data) <= FIXED_BLOCK_SIZE, E_OVERSIZED_MEMORY);
    // Pad to fixed block size — constant gas and constant on-chain size
    let mut padded = memory_data;
    while (vector::length(&padded) < FIXED_BLOCK_SIZE) {
        vector::push_back(&mut padded, 0u8);
    };
    // Only store commitment hash on-chain, not raw data
    dynamic_field::add(&mut wallet.id, b"memory_commit",
        hash::blake2b256(&padded));
}

